/* Quiet Rattlesnake 27 by felipesntr — https://uiverse.io/felipesntr/quiet-rattlesnake-27 */
button {
 padding: 0.6em 1em;
 border: 4px solid #fa725a;
 transition: ease-in-out 0.3s;
 background-color: transparent;
 color: #fa725a;
 font-weight: bolder;
 font-size: 16px;
}

button:hover {
 transform: scale(1.2) rotate(10deg);
 background-color: #fa725a;
 color: white;
}
